// cache-ttl — in-memory cache with TTL eviction
// Backend: mem

fn new_cache::(ttl_ms) {
    return {"ttl": ttl_ms, "items": {}, "stats": {"hits": 0, "misses": 0}};
}

fn is_expired::(entry, now) { return entry["expires"] <= now; }

fn cache_set::(cache, key, value) {
    let now = @time_ms();
    cache["items"][key] = {"value": value, "expires": now + cache["ttl"]};
    return value;
}

fn cache_get::(cache, key) {
    let now = @time_ms();
    if (!@map_has_key(cache["items"], key)) {
        cache["stats"]["misses"] += 1;
        return null;
    }
    let entry = cache["items"][key];
    if (is_expired(entry, now)) {
        cache["items"] = @map_omit_keys(cache["items"], [key]);
        cache["stats"]["misses"] += 1;
        return null;
    }
    cache["stats"]["hits"] += 1;
    return entry["value"];
}

fn cache_has::(cache, key) {
    let now = @time_ms();
    if (!@map_has_key(cache["items"], key)) { return false; }
    return !is_expired(cache["items"][key], now);
}

fn cache_delete::(cache, key) {
    if (@map_has_key(cache["items"], key)) {
        cache["items"] = @map_omit_keys(cache["items"], [key]);
        return true;
    }
    return false;
}

fn cache_purge::(cache) {
    let now = @time_ms();
    let survivors = {};
    for k in @map_keys_sorted(cache["items"]) {
        if (!is_expired(cache["items"][k], now)) { survivors[k] = cache["items"][k]; }
    }
    cache["items"] = survivors;
    return @len(survivors);
}

fn cache_size::(cache) { return @len(cache["items"]); }

fn cache_stats::(cache) {
    let s = cache["stats"];
    let total = s["hits"] + s["misses"];
    return {"hits": s["hits"], "misses": s["misses"],
            "hit_rate": total > 0 ? s["hits"] / total : 0.0};
}

fn cache_clear::(cache) {
    cache["items"] = {};
    cache["stats"] = {"hits": 0, "misses": 0};
    return true;
}

fn version::() { return "1.0.0"; }
